internal static class CableFactorTests {
 static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Near(double a,double b,string label){Check(Math.Abs(a-b)<1e-10,label);}static void Reject(Action a,string label){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static CableFactorRow Row(CableFactorKind kind){return new CableFactorRow{Id=kind==CableFactorKind.Temperature?"T40":"G2",Kind=kind,Material=ConductorMaterial.Copper,Insulation=CableInsulation.PVC,Installation="B1",Arrangement=kind==CableFactorKind.Grouping?"Ensaio: agrupados":"",AmbientC=kind==CableFactorKind.Temperature?40:0,GroupCount=kind==CableFactorKind.Grouping?2:0,LoadedConductors=3,Factor=kind==CableFactorKind.Temperature?.8:.7,AmpacityReference="BASE-QA-1",Source="Tabela sintética; página \"A\" Ω",DataVersion="2026.10"};}
 static Project Fixture(){var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=8*Math.Sqrt(3),PowerFactor=1,BreakerA=25,CableMm2=10,LengthM=10};c.Cable.AmpacityA=50;c.Cable.InstallationMethod="B1";c.Cable.Reference="BASE-QA-1";c.Cable.ResistanceOhmKm=1;c.Cable.ReactanceOhmKm=0;c.Protection.ConventionalTripA=36.25;b.Circuits.Add(c);p.Boards.Add(b);return p;}
 [STAThread] public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"cable-factors-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=Fixture();var c=p.Boards[0].Circuits[0];var conditions=new CableFactorConditions{Arrangement="Ensaio: agrupados",AmbientC=40,GroupCount=2,LoadedConductors=3};var t=Row(CableFactorKind.Temperature);var g=Row(CableFactorKind.Grouping);var rows=new List<CableFactorRow>{t,g};string library=Path.Combine(dir,"factors.csv");CableFactors.Export(rows,library);var read=CableFactors.Import(library);Check(read.Count==2&&read[0].Source==t.Source&&read[1].DataVersion==g.DataVersion,"CSV quotes Unicode and source version roundtrip");CableFactors.Export(new CableFactorRow[0],Path.Combine(dir,"template.csv"));Check(CableFactors.Import(Path.Combine(dir,"template.csv")).Count==0,"empty template imports without factors");
  Check(CableFactors.Filter(read,c,conditions,CableFactorKind.Temperature).Single().Id=="T40","temperature filter matches exact condition");Check(CableFactors.Filter(read,c,conditions,CableFactorKind.Grouping).Single().Id=="G2","group filter matches declared count");conditions.AmbientC=39.9;Check(CableFactors.Filter(read,c,conditions,CableFactorKind.Temperature).Count==0,"no silent interpolation");conditions.AmbientC=40;conditions.GroupCount=3;Check(CableFactors.Filter(read,c,conditions,CableFactorKind.Grouping).Count==0,"wrong group count rejected by filter");conditions.GroupCount=2;conditions.Arrangement="Outro arranjo";Check(CableFactors.Filter(read,c,conditions,CableFactorKind.Grouping).Count==0,"different grouping arrangement does not match");Reject(delegate{CableFactors.Apply(c,conditions,t,g);},"different grouping arrangement cannot be applied");Check(c.Cable.FactorsSnapshot==null&&c.Cable.TemperatureFactor==1,"arrangement mismatch preserves original manual factors");conditions.Arrangement="Ensaio: agrupados";
  CableFactors.Apply(c,conditions,t,g);Near(c.Cable.TemperatureFactor,.8,"temperature factor applied");Near(c.Cable.GroupingFactor,.7,"group factor applied");Near(Engineering.Analyze(p).For(c).CorrectedAmpacityA.Value,28,"Iz product includes both factors");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Condições e referência dos fatores"&&x.Status=="OK"),"reference applicability check passes");c.Cable.Parallel=2;Near(Engineering.Analyze(p).For(c).CorrectedAmpacityA.Value,56,"parallel conductor count applied once");c.Cable.Parallel=1;
  t.Factor=.9;t.Source="Alterado na biblioteca";g.DataVersion="Alterado depois";conditions.AmbientC=30;Check(c.Cable.FactorsSnapshot.Temperature.Factor==.8&&c.Cable.FactorsSnapshot.Temperature.Source.Contains("sintética")&&c.Cable.FactorsSnapshot.Grouping.DataVersion=="2026.10"&&c.Cable.FactorsSnapshot.Conditions.AmbientC==40,"snapshot independent of later library and conditions edits");conditions.AmbientC=40;t=Row(CableFactorKind.Temperature);g=Row(CableFactorKind.Grouping);
  c.Cable.Reference="OTHER";Check(!Engineering.Analyze(p).For(c).CorrectedAmpacityA.HasValue,"mismatched ampacity reference does not reuse corrected Iz");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule.StartsWith("Sobrecarga")&&x.Status=="Pendente"),"wrong correction source cannot approve overload");c.Cable.Reference="BASE-QA-1";c.Cable.Material=ConductorMaterial.Aluminium;Check(!Engineering.Analyze(p).For(c).CorrectedAmpacityA.HasValue,"changed material invalidates factors");c.Cable.Material=ConductorMaterial.Copper;c.Cable.Insulation=CableInsulation.XLPE;Check(!Engineering.Analyze(p).For(c).CorrectedAmpacityA.HasValue,"changed insulation invalidates factors");c.Cable.Insulation=CableInsulation.PVC;c.Cable.InstallationMethod="A1";Check(!Engineering.Analyze(p).For(c).CorrectedAmpacityA.HasValue,"changed installation invalidates factors");c.Cable.InstallationMethod="B1";
  var option=new CableOption{Name="Cabo sintético",Material="Cu",Insulation="PVC",Installation="B1",SectionMm2=10,IzA=50,ResistanceOhmKm=1,ReactanceOhmKm=0,Reference="OTHER"};var evaluation=CableSelection.Evaluate(p,c,option);Check(!evaluation.Iz.HasValue&&evaluation.Status=="Dados incompletos","candidate with wrong reference does not inherit unapplicable correction");option.Reference="BASE-QA-1";Near(CableSelection.Evaluate(p,c,option).Iz.Value,28,"candidate with matching reference retains corrected Iz");
  var old=c.Cable.FactorsSnapshot;conditions.LoadedConductors=2;var t2=t.Copy();var g2=g.Copy();t2.LoadedConductors=g2.LoadedConductors=2;Reject(delegate{CableFactors.Apply(c,conditions,t2,g2);},"three phase cannot declare only two loaded conductors");Check(Object.ReferenceEquals(old,c.Cable.FactorsSnapshot)&&c.Cable.TemperatureFactor==.8,"invalid application leaves prior correction untouched");conditions.LoadedConductors=3;
  t.MinSectionMm2=16;Reject(delegate{CableFactors.Apply(c,conditions,t,g);},"section below factor range rejected");t.MinSectionMm2=0;t.MaxSectionMm2=6;Reject(delegate{CableFactors.Apply(c,conditions,t,g);},"section above factor range rejected");t.MaxSectionMm2=0;
  c.Cable.TemperatureFactor=.9;Reject(p.Validate,"manual factor edit cannot contradict preserved source");c.Cable.TemperatureFactor=.8;
  string project=Path.Combine(dir,"project.circuito");p.Save(project);string saved=File.ReadAllText(project);Check(saved.Contains("\"FileVersion\":4")&&saved.Contains("cable-factors-v1"),"factors use guarded format 4 capability");var loaded=Project.Load(project);var lc=loaded.Boards[0].Circuits[0];Check(lc.Cable.FactorsSnapshot.Conditions.GroupCount==2&&lc.Cable.FactorsSnapshot.Temperature.DataVersion=="2026.10","conditions and source version survive reopen");Near(Engineering.Analyze(loaded).For(lc).CorrectedAmpacityA.Value,28,"reopened corrected ampacity reproducible");
  string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"previous format-4 reader rejects unknown factors capability rather than dropping it");}
  File.WriteAllText(project,saved.Replace("cable-factors-v1","future-factor-v1"));Reject(delegate{Project.Load(project);},"unknown factor capability rejected");File.WriteAllText(project,saved);
  Check(EngineeringReport.Memory(p,Engineering.Analyze(p)).Contains("2026.10")&&EngineeringReport.Memory(p,Engineering.Analyze(p)).Contains("circuitos agrupados 2"),"memory includes actual condition and source version");
  CableFactors.Export(read,library);byte[] before=File.ReadAllBytes(library),backup=File.ReadAllBytes(library+".bak");var invalid=Row(CableFactorKind.Temperature);invalid.Source="";Reject(delegate{CableFactors.Export(new[]{invalid},library);},"missing source rejected");Check(File.ReadAllBytes(library).SequenceEqual(before)&&File.ReadAllBytes(library+".bak").SequenceEqual(backup),"invalid export preserves library and backup");Reject(delegate{CableFactors.Export(new[]{t,t},library);},"duplicate factor IDs rejected");
  foreach(double factor in new[]{0,-1,double.NaN,double.PositiveInfinity}){invalid=Row(CableFactorKind.Temperature);invalid.Factor=factor;Reject(invalid.Validate,"invalid numeric factor rejected");}invalid=Row(CableFactorKind.Temperature);invalid.GroupCount=2;Reject(invalid.Validate,"ignored grouping condition cannot hide in temperature row");invalid=Row(CableFactorKind.Grouping);invalid.AmbientC=40;Reject(invalid.Validate,"ignored ambient condition cannot hide in grouping row");invalid=Row(CableFactorKind.Temperature);invalid.AmbientC=70;Reject(invalid.Validate,"positive factor at PVC temperature limit outside model rejected");invalid=Row(CableFactorKind.Grouping);invalid.Arrangement="";Reject(invalid.Validate,"grouping row requires physical arrangement");invalid=Row(CableFactorKind.Grouping);invalid.GroupCount=0;Reject(invalid.Validate,"zero grouping count rejected");invalid=Row(CableFactorKind.Temperature);invalid.LoadedConductors=5;Reject(invalid.Validate,"unsupported loaded conductor count rejected");invalid=Row(CableFactorKind.Temperature);invalid.MinSectionMm2=16;invalid.MaxSectionMm2=10;Reject(invalid.Validate,"inverted section range rejected");
  string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32*1024*1024+1);Reject(delegate{CableFactors.Import(large);},"oversized import rejected before reading");var huge=new List<CableFactorRow>();string longText=new string('x',2000);for(int i=0;i<6000;i++){var value=Row(CableFactorKind.Temperature);value.Id="BIG-"+i;value.Source=value.DataVersion=value.AmpacityReference=longText;huge.Add(value);}Reject(delegate{CableFactors.Export(huge,library);},"oversized export rejected");Check(File.ReadAllBytes(library).SequenceEqual(before)&&File.ReadAllBytes(library+".bak").SequenceEqual(backup)&&Directory.GetFiles(dir,"*.tmp").Length==0,"size overflow preserves destination backup and removes temporary file");
  var copy=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(copy.Cable.FactorsSnapshot!=c.Cable.FactorsSnapshot&&copy.Cable.FactorsSnapshot.Temperature!=c.Cable.FactorsSnapshot.Temperature,"duplication owns independent reference snapshot");p.Boards[0].Circuits.Remove(copy);
  string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-fatores");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));File.WriteAllText(Path.Combine(artifacts,"resultado.txt"),Engineering.Analyze(p).For(c).CorrectedAmpacityA.Value.ToString("R",System.Globalization.CultureInfo.InvariantCulture));CableFactors.Export(read,Path.Combine(artifacts,"fatores.csv"));
  using(var form=new CableFactorsForm(p,c,library)){form.CreateControl();Check(Field<Button>(form,"apply").Enabled,"editor finds both compatible source rows");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"fatores.png"));}form.Hide();}}
  CableFactors.Remove(c);Check(c.Cable.FactorsSnapshot==null&&c.Cable.TemperatureFactor==.8&&c.Cable.GroupingFactor==.7,"removing source binding preserves manual factor values");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Condições e referência dos fatores"&&x.Status=="Pendente"),"manual factors have explicit reference pending state");
  Console.WriteLine("PASS: "+n+" cable-factor assertions including applicability, snapshots, bounds, import preservation and capability guard");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
